import numpy as np

def conv_layer(X, K, b):
    C_in, H, W = X.shape
    C_out, _, k, _ = K.shape
    Y = np.zeros((C_out, H - k + 1, W - k + 1))
    for o in range(C_out):
        for i in range(H - k + 1):
            for j in range(W - k + 1):
                Y[o, i, j] = (X[:, i:i+k, j:j+k] * K[o]).sum() + b[o]
    return Y
